{
  "findings": [
    {
      "check_id": "CKV_AWS_56",
      "title": "S3 public bucket restrictions disabled",
      "resource": "aws_s3_bucket_public_access_block.api_docs",
      "severity": "MEDIUM",
      "explanation": "The public access block explicitly sets restrict_public_buckets to false, allowing public bucket policies to remain effective."
    },
    {
      "check_id": "CKV_AWS_54",
      "title": "S3 public bucket policies not blocked",
      "resource": "aws_s3_bucket_public_access_block.api_docs",
      "severity": "MEDIUM",
      "explanation": "block_public_policy is not enabled, so new public bucket policies can be applied to the referenced bucket."
    },
    {
      "check_id": "CKV_AWS_53",
      "title": "S3 public ACLs not blocked",
      "resource": "aws_s3_bucket_public_access_block.api_docs",
      "severity": "CRITICAL",
      "explanation": "block_public_acls is not enabled, so public ACLs can be applied to the referenced bucket."
    }
  ],
  "patched_code": "resource \"aws_s3_bucket_public_access_block\" \"api_docs\" {\n  bucket                  = aws_s3_bucket.api_docs.id\n  block_public_acls       = true\n  block_public_policy     = true\n  restrict_public_buckets = true\n}\n",
  "fix_summary": "Enabled blocking of public ACLs and public bucket policies, and restricted existing public bucket policies."
}
